details.definition:
toolRegistry
      ? await buildSystemOneToolSchemas(toolRegistry, disabledTools, {
          ollamaEssentials: isOllama,
          query: latestUserQuery,
          allowedTools: restrictTo,
          // Memory, reminders and skill authoring are what make this an
          // assistant rather than a chat window. Leaving them to `tools.search`
          // costs a round trip, and a model that doesn't take it answers "I
          // can't schedule that" — so they are always on the table.
          activatedToolNames: CHANNEL_ACTIVATED_TOOLS,
        }, auth?.apiKeys)
      : []

sqliteTable(
  "session_events",
  {
    sessionId: text("session_id").notNull(),
    logId: integer("log_id").notNull(),
    type: text("type").notNull(),
    payload: text("payload").notNull(), // JSON serialized stream event
    createdAt: integer("created_at").notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.sessionId, table.logId] }),
  ],
)

sqliteTable(
  "session_state",
  {
    sessionId: text("session_id").notNull(),
    key: text("key").notNull(),
    value: text("value"),       // JSON-serialized
    updatedAt: text("updated_at").notNull(),
  },
  (table) => [
    index("idx_session_state_session").on(table.sessionId),
  ],
)

sqliteTable(
  "project_state",
  {
    projectId: text("project_id").notNull(),
    key: text("key").notNull(),
    value: text("value"),
    updatedAt: text("updated_at").notNull(),
  },
  (table) => [
    index("idx_project_state_project").on(table.projectId),
  ],
)

sqliteTable("persona_agents", {
  id: text("id").primaryKey(),
  userId: text("user_id").notNull(),
  data: text("data").notNull(),
  updatedAt: text("updated_at").notNull(),
}, (table) => [index("idx_persona_agents_user").on(table.userId)])

sqliteTable("thread_recovery", {
  threadId: text("thread_id").primaryKey(),
  attempts: integer("attempts").notNull().default(0),
  staleProviderSessionId: text("stale_provider_session_id"),
  pending: integer("pending", { mode: "boolean" }).notNull().default(true),
})

sqliteTable(
  "users",
  {
    id: text("id").primaryKey(),
    username: text("username").notNull().unique(),
    passwordHash: text("password_hash").notNull(),
    createdAt: text("created_at").notNull(),
    updatedAt: text("updated_at").notNull(),
  },
  (table) => [
    index("idx_users_username").on(table.username),
  ],
)

sqliteTable(
  "node_permissions",
  {
    nodeId: text("node_id").notNull(),
    capability: text("capability").notNull(), // 'terminal'|'filesystem'|'screen'|'voice'|'browser'|'camera'|'network'
    granted: integer("granted").notNull().default(0), // 0 = denied, 1 = granted
    updatedAt: text("updated_at").notNull(),
  },
  (table) => [
    // Composite PK — one row per (node, capability) grant.
    primaryKey({ columns: [table.nodeId, table.capability] }),
  ],
)

sqliteTable("node_credentials", {
  tokenHash: text("token_hash").primaryKey(),
  nodeId: text("node_id").notNull(),
  userId: text("user_id").notNull(),
  createdAt: text("created_at").notNull(),
})

sqliteTable("account_invitations", {
  tokenHash: text("token_hash").primaryKey(),
  createdBy: text("created_by").notNull(),
  expiresAt: text("expires_at").notNull(),
})

sqliteTable("team_rooms", {
  id: text("id").primaryKey(),
  userId: text("user_id").notNull(),
  rootAgentId: text("root_agent_id").notNull(),
  data: text("data").notNull(),
}, table => [index("idx_team_room_root").on(table.userId, table.rootAgentId)])

sqliteTable("team_room_messages", {
  id: text("id").primaryKey(),
  roomId: text("room_id").notNull(),
  clientKey: text("client_key").notNull(),
  data: text("data").notNull(),
}, table => [uniqueIndex("idx_team_message_key").on(table.roomId, table.clientKey)])

sqliteTable(
  "projects",
  {
    id: text("id").primaryKey(),
    userId: text("user_id"),
    title: text("title"),
    rootPath: text("root_path"),
    nodeId: text("node_id"),
    createdAt: text("created_at").notNull(),
    lastActiveAt: text("last_active_at").notNull(),
    status: text("status").default("active"),
    metadata: text("metadata"),
    /** Parent folder, or null at the root. Only `kind: 'folder'` rows may be parents. */
    parentId: text("parent_id"),
    /** Extra context injected into the system prompt of every chat below this node. */
    instructions: text("instructions"),
    /** Free-text description shown in the UI. */
    description: text("description"),
    /** Palette token (e.g. "blue") or a `#rrggbb` value from the colour picker. */
    color: text("color"),
    /** 'workspace' (folder on disk) | 'folder' (pure chat category) */
    kind: text("kind").notNull().default("workspace"),
  },
  (table) => [
    index("idx_projects_user_status").on(table.userId, table.status, table.lastActiveAt),
    index("idx_projects_user_root").on(table.userId, table.rootPath, table.nodeId),
    index("idx_projects_parent").on(table.userId, table.parentId, table.status, table.lastActiveAt),
  ],
)

sqliteTable("trust_levels", {
  actionType: text("action_type").primaryKey(), // e.g. 'terminal.run'
  approvedCount: integer("approved_count").default(0),
  revertedCount: integer("reverted_count").default(0),
  currentLevel: integer("current_level").default(0), // 0=observer,1=assisted,2=trusted,3=autopilot
})

sqliteTable("consent_session_approvals", {
  sessionId: text("session_id").primaryKey(),
  approveAll: integer("approve_all").notNull().default(1), // 1 = enabled
  updatedAt: text("updated_at").notNull(),
})

{
    fullSchema: schema,
