        name: {
          type: "string",
          description: "Cron job name (for cron.add).",
        },
        cron: {
          type: "string",
          description: 'Cron expression (for cron.add/update). E.g. "0 9 * * *" for daily at 9am.',
        },
        toolName: {
          type: "string",
          description: "Tool name to execute on schedule (for cron.add).",
        },
        input: {
          type: "object",
          description: "Tool input arguments (for cron.add/update).",
        },
        jobId: {
          type: "string",
          description: "Cron job ID (for cron.update/remove).",
        },
        enabled: {
          type: "boolean",
          description: "Enable/disable toggle (for cron.update).",
        },
      },
      required: ["action"],
    }

{
      type: "object",
      properties: {
        path: {
          type: "string",
          description: "File or directory path.",
        },
        startLine: {
          type: "number",
          description: "1-based start line.",
        },
        endLine: {
          type: "number",
          description: "1-based end line (inclusive).",
        },
      },
      required: ["path"],
    }

{
      type: "object",
      properties: {
        pattern: {
          type: "string",
          description: "Text or regex pattern to search for.",
        },
        isRegexp: {
          type: "boolean",
          description: "True if pattern is a regex.",
        },
        path: {
          type: "string",
          description: "Directory to search in (defaults to project root).",
        },
        mode: {
          type: "string",
          description: '"content" (grep, default) or "files" (find by name).',
          enum: ["content", "files"],
        },
        include: {
          type: "string",
          description: 'File glob filter (e.g. "*.ts", "src/**").',
        },
