export interface AgentHaltResult {
  state: AgentControlState;
  stopped: number;
  /** Halt is persisted even when an individual runner refuses to stop. */
  stopError: string | null;
}

export interface AgentControlState {
  halted: boolean;
  reason: string | null;
  haltedAt: string | null;
  updatedAt: string | null;
}

export type JaitPageFeature = { id: string; description: string } & (
  | { toolRefs: readonly [string, ...string[]]; uiOnlyReason?: never }
  | { toolRefs: readonly []; uiOnlyReason: string }
);

export interface JaitPageContract {
  title: string;
  path: string;
  mode: "developer" | "manager" | "both";
  description: string;
  examples: readonly string[];
  features: readonly JaitPageFeature[];
  /** Supported URL parameters for agent links and shareable page searches. */
  queryParameters?: Readonly<Record<string, string>>;
  /** New tools in these namespaces automatically join the page. */
  toolPrefixes: readonly string[];
}

export interface CodeGraphSnapshot {
  index: CodeGraphIndex;
  nodes: CodeGraphNode[];
  edges: CodeGraphEdge[];
  truncated: boolean;
}

export interface CodeGraphQueryResult {
  query: string;
  mode: "structural" | "global" | "hybrid";
  context: string;
  nodes: CodeGraphNode[];
  edges: CodeGraphEdge[];
  graphVersion?: string | null;
  graphRagStatus: GraphRagIndexStatus;
}

export interface CodeGraphPathResult {
  source: CodeGraphNode;
  target: CodeGraphNode;
  nodes: CodeGraphNode[];
  edges: CodeGraphEdge[];
}

export interface GraphRagExportManifest {
  schemaVersion: 1;
  graphVersion: string;
  generatedAt: string;
  entitiesPath: string;
  relationshipsPath: string;
  textUnitsPath: string;
  entityCount: number;
  relationshipCount: number;
  textUnitCount: number;
}

export interface CodeGraphNode {
  id: string;
  label: string;
  type: string;
  fileType?: string;
  sourceFile?: string;
  line?: number;
  endLine?: number;
  community?: string;
  degree: number;
  properties: Record<string, unknown>;
}

export interface CodeGraphEdge {
  id: string;
  source: string;
  target: string;
  relation: string;
  confidence: CodeGraphConfidence;
  confidenceScore?: number;
  sourceFile?: string;
  line?: number;
  properties: Record<string, unknown>;
}

export interface CodeGraphStats {
  nodeCount: number;
  edgeCount: number;
  communityCount: number;
  nodeTypes: Record<string, number>;
  relations: Record<string, number>;
  confidence: Record<CodeGraphConfidence, number>;
}

export interface CodeGraphIndex {
  id: string;
  projectRoot: string;
  repositoryId?: string | null;
  provider: "graphify";
  status: CodeGraphIndexStatus;
  graphPath?: string | null;
  graphVersion?: string | null;
  sourceRevision?: string | null;
  graphifyVersion?: string | null;
  stats?: CodeGraphStats | null;
  graphRagStatus: GraphRagIndexStatus;
  graphRagPath?: string | null;
  error?: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface DesktopGatewayStatus {
  config: DesktopGatewayConfig;
  state: 'stopped' | 'starting' | 'running' | 'stopping' | 'failed';
  url: string | null;
  error: string | null;
  logs: string[];
}

export interface DesktopGatewayConfig {
  mode: 'local' | 'remote';
  remoteUrl: string | null;
  port: number;
  allowNetwork: boolean;
}

export interface EmailMessageFull extends EmailMessageSummary {
  cc: string;
  bodyText: string;
  bodyHtml: string;
}

export interface EmailFolder {
  id: string;
  name: string;
  unreadCount?: number;
}

export interface ListMessagesOptions {
  folder?: string;
  query?: string;
  limit?: number;
}

export interface SendMessageInput {
  to: string;
  subject: string;
  body: string;
  cc?: string;
  bcc?: string;
  /** When set, send as a reply within this message's thread. */
  replyToMessageId?: string;
  /** Send the body as HTML instead of plain text. */
  html?: boolean;
  includeSignature?: boolean;
}

export interface EmailAccount {
  id: string;
  userId: string | null;
  provider: EmailProvider;
  email: string;
  displayName: string;
  signature?: string;
  signatureEnabled?: boolean;
  status: "connected" | "error";
  error?: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface MailServerConfig {
  host: string;
  port: number;
  /** false requires STARTTLS; cleartext authentication is never allowed. */
  secure: boolean;
  user: string;
  password: string;
}

export interface ConnectMailboxInput {
  email: string;
  displayName?: string;
  imap: MailServerConfig;
  smtp: MailServerConfig;
}

export interface EmailAccountSettings {
  displayName?: string;
  signature?: string;
  signatureEnabled?: boolean;
}

export interface DiscoveredMailSettings {
  name: string;
  imap: Omit<MailServerConfig, "password">;
  smtp: Omit<MailServerConfig, "password">;
}

export interface EmailTokens {
  accessToken: string;
  refreshToken: string | null;
  /** Epoch milliseconds when the access token expires. */
  expiresAt: number;
  scope?: string;
}

export interface EmailMessageSummary {
  id: string;
  threadId?: string;
  from: string;
  to: string;
  subject: string;
  snippet: string;
  date: string;
  unread: boolean;
  /** Provider label / category names attached to the message. */
  labels: string[];
  hasAttachments: boolean;
}

export interface JaitBackendInstanceConfig {
  id: string;
  type: JaitBackend;
  name: string;
  baseUrl: string;
  apiKey?: string;
  model?: string;
  numCtx?: number;
}

export interface JaitRenderedLink {
  kind: "jait-link";
  href: string;
  label: string;
}

export interface MessengerToolResponse {
  ok: boolean;
  message: string;
  data?: unknown;
}

export interface MessengerReadReceipt {
  userId: string
  name: string
  timestamp: number | null
  /** False means this is a later read watermark, not the exact first-read time. */
  exact: boolean
}

export interface MessengerRoomPeer {
  userId: string
  name: string
  /** Matrix `mxc://` avatar, resolved through the gateway media route. */
  avatarUrl?: string
  presence: MessengerPresence
  /** Milliseconds since the peer was last active, when the homeserver reports it. */
  lastActiveAgo?: number
}

export interface MessengerRoom {
  id: string
  name: string
  service: string
  network: string
  unread: number
  markedUnread?: boolean
  membership: string
  encrypted: boolean
  timestamp: number
  preview: string
  /** WhatsApp status broadcasts have no real timeline; they get a dedicated read-only view. */
  status?: boolean
  /** Structural shape of the room. Absent means a plain chat. */
  kind?: MessengerRoomKind
  /** Team/workspace this room belongs to (Slack workspace, Teams team, Discord guild). */
  team?: string
  /** Room topic, surfaced on channel headers. */
  topic?: string
  /** Room avatar, or the counterpart's avatar for direct chats (`mxc://`). */
  avatarUrl?: string
  /** Set for direct conversations with exactly one other participant. */
  peer?: MessengerRoomPeer
}

export interface MessengerRequest {
  requestId: string;
  expiresAt: number;
  command: MessengerCommand;
}

export interface UsageSummary {
  durationMs: number;
  promptTokens?: number;
  cachedPromptTokens?: number;
  completionTokens?: number;
  totalTokens?: number;
  tokenUsageEstimated?: boolean;
  requestCount?: number;
}

export interface ModelUsage {
  inputTokens: number;
  outputTokens: number;
  cachedInputTokens?: number;
  totalTokens?: number;
  /** Session counters need a saved baseline; a turn counter is already attributable. */
  scope: "session" | "turn";
  /** Stable ID for updates to one provider turn. */
  id?: string;
  /** Only populated when the provider reports it. */
  requestCount?: number;
  lastRequest?: Omit<ModelUsage, "scope" | "id" | "lastRequest">;
}

export interface NetworkResourceInventory {
  status: 'available' | 'unavailable'
  resources: NetworkResource[]
  truncated?: boolean
}

export interface NotificationContext {
  link?: string;
  replaceId?: string;
  kind?: "completion" | "attention";
  sessionId?: string;
}

export interface ChatNotificationState {
  id: string;
  sessionId: string;
  replaceId: string;
  read: boolean;
}

export interface NotificationActivation {
  id: string;
  link: string;
  scope?: string;
}

export interface OllamaUsageSetup {
  host: string;
  platform: string;
  gatewayUser: string;
  local: boolean;
  keyStatus: "remote" | "missing" | "unreadable" | "readable";
  keyPath: string | null;
  permissionCommand: string | null;
}

export interface ChatPersona {
  id: string;
  name: string;
  avatar: string;
  role?: string;
  providerId: string;
  model?: string | null;
}

export interface ProjectTreeNodeInput {
  id: string
  parentId?: string | null
  kind?: string | null
}

export interface ProjectTreeNode<T extends ProjectTreeNodeInput> {
  project: T
  depth: number
  children: ProjectTreeNode<T>[]
}

export interface InstructionChainEntry {
  id: string
  title: string | null
  instructions: string
}

export interface SavedProjectPanelState {
  open?: boolean
}

export interface ProviderDeviceAuthDetails {
  verificationUri?: string
  userCode?: string
  requiresCodeInput?: boolean
  inputPrompt?: string
}

