export interface SecurityScopeInput {
  targets: string[];
  exclusions: string[];
  ports: number[];
  expiresAt: string;
  authorized: boolean;
  methods?: import("./security-workbench.js").SecurityMethod[];
  paths?: string[];
  serverNames?: string[];
  sshUsernames?: string[];
}

export interface SecurityCheckRun {
  id: string;
  operatorId: string;
  scopeId: string;
  scope: import("./security-assessment.js").SecurityScope;
  input: SecurityCheckInput;
  profileRevision: "security-profiles-v1";
  status: "running" | "completed" | "partial" | "cancelled" | "unavailable" | "interrupted";
  startedAt: string;
  completedAt: string | null;
  engine: string;
  engineVersion: string;
  evidence: SecurityEvidence[];
  findingIds: string[];
  findings: SecurityFinding[];
  coverageGaps: string[];
  artifact?: { id: string; sha256: string; bytes: number; contentType: string };
